"""Runtime guardrail plugin generated by EvalLoop.

Enforces the runtime subset of criteria from `evalloop/criteria/bigquery_agent_safety.yaml`
at agent tool execution boundaries.

Usage in ADK (the installed `evalloop` package shadows this directory, so
`from evalloop.guardrail import ...` does not resolve; load the pack directly):
    from google.adk.apps import App
    from evalloop.adk import EvalLoopPlugin

    app = App(
        ...,
        plugins=[EvalLoopPlugin.from_file("evalloop/criteria/bigquery_agent_safety.yaml")],
    )
"""

from __future__ import annotations

import pathlib

from evalloop import adk as adk_plugin
from evalloop.loader import load_pack

CRITERIA_FILE = pathlib.Path(__file__).parent / "criteria" / "bigquery_agent_safety.yaml"


def get_guardrail_plugin() -> adk_plugin.EvalLoopPlugin:
    """Returns an initialized EvalLoopPlugin for this repository's criteria."""
    pack = load_pack(CRITERIA_FILE)
    return adk_plugin.EvalLoopPlugin(pack=pack)
